<?php
/**
 * CBT MTs Darul Muhsinin NW Surabaya Utara
 * Lightweight single-file PHP + SQLite application.
 * Demo accounts: admin / admin123 and 1234567890 / siswa123.
 * Change demo passwords before using with real student data.
 */
declare(strict_types=1);
session_start();
const DB_FILE = __DIR__ . '/cbt.sqlite';

try {
    $db = new PDO('sqlite:' . DB_FILE, null, null, [PDO::ATTR_ERRMODE => PDO::ERRMODE_EXCEPTION, PDO::ATTR_DEFAULT_FETCH_MODE => PDO::FETCH_ASSOC]);
    $db->exec('PRAGMA foreign_keys = ON');
    $db->exec("CREATE TABLE IF NOT EXISTS users (id INTEGER PRIMARY KEY, username TEXT UNIQUE NOT NULL, password TEXT NOT NULL, name TEXT NOT NULL, role TEXT NOT NULL, grade TEXT DEFAULT '')");
    $db->exec("CREATE TABLE IF NOT EXISTS exams (id INTEGER PRIMARY KEY, title TEXT NOT NULL, subject TEXT NOT NULL, grade TEXT NOT NULL, duration INTEGER NOT NULL, shuffle INTEGER NOT NULL DEFAULT 1, active INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP)");
    $db->exec("CREATE TABLE IF NOT EXISTS questions (id INTEGER PRIMARY KEY, exam_id INTEGER NOT NULL REFERENCES exams(id) ON DELETE CASCADE, prompt TEXT NOT NULL, options TEXT NOT NULL, correct INTEGER NOT NULL)");
    $db->exec("CREATE TABLE IF NOT EXISTS attempts (id INTEGER PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id), exam_id INTEGER NOT NULL REFERENCES exams(id), started_at INTEGER NOT NULL, deadline INTEGER NOT NULL, status TEXT NOT NULL DEFAULT 'ongoing', answers TEXT NOT NULL DEFAULT '{}', doubtful TEXT NOT NULL DEFAULT '[]', score INTEGER NOT NULL DEFAULT 0, total INTEGER NOT NULL DEFAULT 0, submitted_at TEXT)");
    if ((int)$db->query('SELECT COUNT(*) FROM users')->fetchColumn() === 0) {
        $add = $db->prepare('INSERT INTO users(username,password,name,role,grade) VALUES(?,?,?,?,?)');
        $add->execute(['admin', password_hash('admin123', PASSWORD_DEFAULT), 'Guru / Administrator', 'admin', '']);
        $add->execute(['1234567890', password_hash('siswa123', PASSWORD_DEFAULT), 'Siswa Contoh', 'student', '7']);
    }
    if ((int)$db->query('SELECT COUNT(*) FROM exams')->fetchColumn() === 0) {
        $db->exec("INSERT INTO exams(title,subject,grade,duration,shuffle,active) VALUES ('Latihan Asesmen Semester','Matematika','7',30,1,1)");
        $seed = $db->prepare('INSERT INTO questions(exam_id,prompt,options,correct) VALUES(1,?,?,?)');
        $seed->execute(['Hasil dari 12 × 8 adalah …', json_encode(['86','96',' દ6','108'], JSON_UNESCAPED_UNICODE), 1]);
        $seed->execute(['Bangun datar yang memiliki tiga sisi disebut …', json_encode(['Persegi','Segitiga','Lingkaran','Trapesium'], JSON_UNESCAPED_UNICODE), 1]);
        $seed->execute(['Nilai tempat angka 5 pada bilangan 3.572 adalah …', json_encode(['Satuan','Puluhan','Ratusan','Ribuan'], JSON_UNESCAPED_UNICODE), 2]);
    }
} catch (Throwable $e) { http_response_code(500); exit('Database tidak dapat dibuka. Pastikan PHP memiliki ekstensi PDO SQLite dan folder aplikasi dapat ditulis.'); }

function h(string $s): string { return htmlspecialchars($s, ENT_QUOTES, 'UTF-8'); }
function user(): ?array { return $_SESSION['user'] ?? null; }
function csrf(): string { if (empty($_SESSION['csrf'])) $_SESSION['csrf'] = bin2hex(random_bytes(24)); return $_SESSION['csrf']; }
function go(string $url = 'index.php'): never { header('Location: ' . $url); exit; }
function notice(string $text, string $kind = 'success'): void { $_SESSION['flash'] = [$text, $kind]; }
function requireRole(string $role): void { if (!user() || user()['role'] !== $role) go(); }
function examById(PDO $db, int $id): ?array { $q=$db->prepare('SELECT * FROM exams WHERE id=?'); $q->execute([$id]); return $q->fetch() ?: null; }

if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    if (!hash_equals(csrf(), (string)($_POST['csrf'] ?? ''))) { http_response_code(403); exit('Token keamanan tidak valid. Muat ulang halaman.'); }
    $action = (string)($_POST['action'] ?? '');
    if ($action === 'login') {
        $q=$db->prepare('SELECT * FROM users WHERE username=?'); $q->execute([trim((string)($_POST['username'] ?? ''))]); $u=$q->fetch();
        if ($u && password_verify((string)($_POST['password'] ?? ''), $u['password'])) { session_regenerate_id(true); $_SESSION['user']=['id'=>(int)$u['id'],'name'=>$u['name'],'username'=>$u['username'],'role'=>$u['role'],'grade'=>$u['grade']]; go(); }
        notice('Username/NISN atau password tidak sesuai.','error'); go();
    }
    if ($action === 'logout') { $_SESSION=[]; session_destroy(); go(); }
    if (!user()) go();
    if ($action === 'create_exam' && user()['role']==='admin') {
        $title=trim((string)($_POST['title']??'')); $subject=trim((string)($_POST['subject']??'')); $grade=(string)($_POST['grade']??''); $duration=(int)($_POST['duration']??0);
        if ($title && $subject && in_array($grade,['7','8','9'],true) && $duration>=1 && $duration<=300) { $q=$db->prepare('INSERT INTO exams(title,subject,grade,duration,shuffle,active) VALUES(?,?,?,?,?,1)'); $q->execute([$title,$subject,$grade,$duration,isset($_POST['shuffle'])?1:0]); notice('Ujian berhasil dibuat. Tambahkan soal pada panel ujian.'); }
        else notice('Lengkapi data ujian dengan benar.','error'); go();
    }
    if ($action === 'add_question' && user()['role']==='admin') {
        $examId=(int)($_POST['exam_id']??0); $prompt=trim((string)($_POST['prompt']??'')); $opts=array_map('trim',array_slice((array)($_POST['options']??[]),0,4)); $correct=(int)($_POST['correct']??-1);
        if (examById($db,$examId) && $prompt && count($opts)===4 && !in_array('', $opts, true) && $correct>=0 && $correct<4) { $q=$db->prepare('INSERT INTO questions(exam_id,prompt,options,correct) VALUES(?,?,?,?)'); $q->execute([$examId,$prompt,json_encode($opts,JSON_UNESCAPED_UNICODE),$correct]); notice('Soal berhasil ditambahkan.'); }
        else notice('Periksa kembali teks soal dan keempat pilihan jawaban.','error'); go();
    }
    if ($action === 'start' && user()['role']==='student') {
        $examId=(int)($_POST['exam_id']??0); $exam=examById($db,$examId);
        if ($exam && $exam['active'] && (string)$exam['grade']===(string)user()['grade']) {
            $q=$db->prepare("SELECT * FROM attempts WHERE user_id=? AND exam_id=? AND status='ongoing' ORDER BY id DESC LIMIT 1"); $q->execute([user()['id'],$examId]); $attempt=$q->fetch();
            if (!$attempt) {
                $q=$db->prepare('SELECT id,options FROM questions WHERE exam_id=? ORDER BY id'); $q->execute([$examId]); $questions=$q->fetchAll();
                if (!$questions) { notice('Ujian belum memiliki soal.','error'); go(); }
                $order=array_column($questions,'id'); if ($exam['shuffle']) shuffle($order);
                $optionOrders=[]; foreach($questions as $question){$opts=json_decode($question['options'],true)?:[];$idx=array_keys($opts);if($exam['shuffle'])shuffle($idx);$optionOrders[$question['id']]=$idx;}
                $now=time(); $q=$db->prepare("INSERT INTO attempts(user_id,exam_id,started_at,deadline,status,answers,doubtful,total) VALUES(?,?,?,?, 'ongoing','{}','[]',?)"); $q->execute([user()['id'],$examId,$now,$now+(int)$exam['duration']*60,json_encode(['questions'=>$order,'options'=>$optionOrders]),count($questions)]); $attemptId=(int)$db->lastInsertId();
            } else $attemptId=(int)$attempt['id'];
            go('index.php?take='.$attemptId);
        } notice('Ujian tidak tersedia untuk kelas Anda.','error'); go();
    }
    if (in_array($action,['save_answer','toggle_doubt','submit_exam'],true) && user()['role']==='student') {
        $id=(int)($_POST['attempt_id']??0); $q=$db->prepare("SELECT * FROM attempts WHERE id=? AND user_id=? AND status='ongoing'"); $q->execute([$id,user()['id']]); $attempt=$q->fetch();
        if (!$attempt) { if(isset($_POST['ajax'])){http_response_code(404);exit('Ujian tidak ditemukan.');} go(); }
        if ($action==='save_answer') {
            $answers=json_decode($attempt['answers'],true)?:[]; $qid=(string)(int)($_POST['question_id']??0); $choice=(int)($_POST['choice']??-1); $state=json_decode($attempt['doubtful'],true)?:[];
            if (time() >= (int)$attempt['deadline']) $action='submit_exam';
            else { if($choice<0)unset($answers[$qid]);else $answers[$qid]=$choice; $q=$db->prepare('UPDATE attempts SET answers=? WHERE id=?');$q->execute([json_encode($answers),$id]); if(isset($_POST['ajax'])){header('Content-Type: application/json');echo json_encode(['ok'=>true]);exit;} }
        }
        if ($action==='toggle_doubt') { $d=json_decode($attempt['doubtful'],true)?:[];$qid=(int)($_POST['question_id']??0);if(in_array($qid,$d,true))$d=array_values(array_diff($d,[$qid]));else$d[]=$qid;$q=$db->prepare('UPDATE attempts SET doubtful=? WHERE id=?');$q->execute([json_encode($d),$id]);go('index.php?take='.$id.'&q='.$qid); }
        if ($action==='submit_exam') {
            $answers=json_decode($attempt['answers'],true)?:[];$state=json_decode($attempt['doubtful'],true)?:[];$meta=json_decode($attempt['doubtful'],true)?:[];
            $q=$db->prepare('SELECT id,correct FROM questions WHERE exam_id=?');$q->execute([$attempt['exam_id']]);$questions=$q->fetchAll();$score=0;foreach($questions as $question)if(isset($answers[(string)$question['id']])&&(int)$answers[(string)$question['id']] === (int)$question['correct'])$score++;
            $q=$db->prepare("UPDATE attempts SET status='submitted',score=?,total=?,submitted_at=CURRENT_TIMESTAMP WHERE id=?");$q->execute([$score,count($questions),$id]);notice('Jawaban ujian berhasil dikirim.');go('index.php?result='.$id);
        }
    }
}

$me=user(); $flash=$_SESSION['flash']??null;unset($_SESSION['flash']);
?><!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#102b25"><title>CBT — MTs Darul Muhsinin</title><style>
:root{--ink:#172b27;--muted:#71817c;--green:#176b51;--mint:#e8f4ed;--line:#e4eae6;--paper:#f5f7f4;--gold:#dda94a;--red:#c14e45}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:15px/1.5 Inter,ui-sans-serif,system-ui,-apple-system,"Segoe UI",sans-serif}button,input,select,textarea{font:inherit}button{cursor:pointer}.top{background:#102b25;color:#fff;padding:15px max(22px,calc((100% - 1120px)/2));display:flex;align-items:center;justify-content:space-between}.brand{display:flex;gap:12px;align-items:center}.logo{width:38px;height:38px;border-radius:12px;background:#d9eedf;color:#155942;display:grid;place-items:center;font-weight:900}.brand strong{display:block;font-size:15px}.brand small{color:#b4ccc1}.topright{display:flex;gap:14px;align-items:center}.container{max-width:1120px;margin:34px auto;padding:0 22px}.eyebrow{color:var(--green);font-size:12px;font-weight:800;letter-spacing:.13em;text-transform:uppercase}.hero{margin-bottom:26px}.hero h1{font-size:30px;line-height:1.15;letter-spacing:-.04em;margin:8px 0}.hero p{color:var(--muted);margin:0}.grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px}.card{background:white;border:1px solid var(--line);border-radius:16px;padding:21px;box-shadow:0 5px 20px #17372b08}.card h2,.card h3{margin:0 0 8px;letter-spacing:-.02em}.card h2{font-size:19px}.muted{color:var(--muted)}.badge{display:inline-flex;background:var(--mint);color:#236448;border-radius:30px;padding:4px 10px;font-size:12px;font-weight:700}.meta{display:flex;gap:8px;flex-wrap:wrap;margin:15px 0}.btn{border:0;border-radius:10px;padding:10px 15px;background:var(--green);color:white;font-weight:750}.btn:hover{background:#10533e}.btn.secondary{background:#edf2ee;color:#28483c}.btn.danger{background:#a83c36}.btn.small{padding:7px 11px;font-size:13px}.row{display:flex;align-items:center;justify-content:space-between;gap:10px}.field{margin:12px 0}.field label{display:block;font-size:13px;font-weight:700;margin-bottom:6px}.field input,.field select,.field textarea{width:100%;border:1px solid #dce5df;border-radius:10px;padding:11px 12px;background:#fff;color:var(--ink)}.field textarea{min-height:84px;resize:vertical}.formcard{max-width:480px;margin:55px auto}.notice{padding:11px 14px;border-radius:10px;margin-bottom:16px;background:#e8f4ed;color:#246246}.notice.error{background:#fff0ed;color:#a33f37}.stats{display:flex;gap:12px;margin:18px 0}.stat{background:#f5f8f5;border:1px solid var(--line);padding:12px 16px;border-radius:12px;flex:1}.stat strong{font-size:21px;display:block}.tablewrap{overflow:auto}table{width:100%;border-collapse:collapse;min-width:600px}th,td{text-align:left;padding:12px;border-bottom:1px solid var(--line)}th{font-size:12px;text-transform:uppercase;color:var(--muted)}.testlayout{display:grid;grid-template-columns:minmax(0,1fr) 260px;gap:18px}.timer{font-size:21px;font-variant-numeric:tabular-nums;font-weight:850;color:#245e48}.question{font-size:21px;font-weight:750;margin:22px 0}.choice{display:flex;gap:11px;align-items:flex-start;border:1px solid var(--line);border-radius:11px;padding:13px;margin:9px 0;cursor:pointer}.choice:has(input:checked){border-color:var(--green);background:#f0f7f2}.choice input{margin-top:4px;accent-color:var(--green)}.numbers{display:grid;grid-template-columns:repeat(5,1fr);gap:8px;margin:15px 0}.num{height:39px;border:1px solid var(--line);border-radius:9px;background:#fff;font-weight:700;color:#45574f}.num.answered{background:#dff0e5;border-color:#c4e3ce}.num.doubt{box-shadow:inset 0 -4px #e4ad43}.num.current{outline:2px solid var(--green)}.legend{font-size:12px;color:var(--muted);display:grid;gap:7px;margin:14px 0}.dot{display:inline-block;width:10px;height:10px;border-radius:3px;margin-right:6px;background:#dff0e5}.dot.gold{background:#f1d899}.footer{text-align:center;color:#83918b;padding:25px;font-size:12px}.loginwrap{min-height:100vh;display:grid;grid-template-columns:1fr 1fr}.loginhero{background:#102b25;color:#fff;padding:10vw 9vw;display:flex;flex-direction:column;justify-content:center}.loginhero h1{font-size:clamp(34px,5vw,58px);letter-spacing:-.06em;line-height:1.05;margin:20px 0}.loginhero p{color:#bad0c5;max-width:420px}.loginpane{display:grid;place-items:center;padding:24px}.loginpane .card{width:min(420px,100%);padding:32px}.subtle{font-size:12px;color:var(--muted);line-height:1.5}.checkbox{display:flex;align-items:center;gap:8px;font-size:13px}.inline{display:inline}.right{text-align:right}@media(max-width:800px){.grid{grid-template-columns:repeat(2,minmax(0,1fr))}.testlayout{grid-template-columns:1fr}.numbers{grid-template-columns:repeat(6,1fr)}.loginwrap{grid-template-columns:1fr}.loginhero{padding:40px 28px}.loginhero h1{font-size:38px}.container{margin:24px auto}}@media(max-width:520px){.grid{grid-template-columns:1fr}.top{padding:13px 16px}.topright .name{display:none}.container{padding:0 14px}.numbers{grid-template-columns:repeat(5,1fr)}.hero h1{font-size:26px}}
</style></head><body><?php if(!$me): ?><main class="loginwrap"><section class="loginhero"><div class="brand"><div class="logo">DM</div><div><strong>MTs Darul Muhsinin</strong><small>NW Surabaya Utara</small></div></div><div><div class="eyebrow" style="color:#a7d6bc">Ujian digital, lebih mudah</div><h1>Belajar dengan<br>fokus. Ujian dengan<br>percaya diri.</h1><p>Platform asesmen modern untuk siswa kelas 7–9, mata pelajaran umum, keagamaan, dan muatan lokal.</p></div><small style="color:#91afa0">Computer-Based Test · Madrasah Tsanawiyah</small></section><section class="loginpane"><div class="card"><div class="eyebrow">Selamat datang</div><h2 style="font-size:27px;margin:7px 0">Masuk ke akun CBT</h2><p class="muted">Gunakan NISN / username dan password Anda.</p><?php if($flash): ?><div class="notice <?=h($flash[1])?>"><?=h($flash[0])?></div><?php endif ?><form method="post"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><input type="hidden" name="action" value="login"><div class="field"><label>NISN / Username</label><input name="username" autocomplete="username" required autofocus placeholder="Masukkan NISN atau username"></div><div class="field"><label>Password</label><input type="password" name="password" autocomplete="current-password" required placeholder="Masukkan password"></div><button class="btn" style="width:100%;margin-top:7px">Masuk ke CBT →</button></form><p class="subtle" style="margin-top:19px">Demo siswa: <b>1234567890</b> / <b>siswa123</b><br>Demo guru: <b>admin</b> / <b>admin123</b></p></div></section></main><?php else: ?><header class="top"><div class="brand"><div class="logo">DM</div><div><strong>CBT MTs Darul Muhsinin</strong><small>NW Surabaya Utara</small></div></div><div class="topright"><span class="name"><?=h($me['name'])?> · <?= $me['role']==='admin'?'Guru/Admin':'Kelas '.$me['grade'] ?></span><form method="post" class="inline"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><input type="hidden" name="action" value="logout"><button class="btn secondary small">Keluar</button></form></div></header><main class="container"><?php if($flash): ?><div class="notice <?=h($flash[1])?>"><?=h($flash[0])?></div><?php endif ?>
<?php if(isset($_GET['take']) && $me['role']==='student'):
$id=(int)$_GET['take'];$q=$db->prepare("SELECT a.*,e.title,e.subject,e.grade,e.shuffle FROM attempts a JOIN exams e ON e.id=a.exam_id WHERE a.id=? AND a.user_id=?");$q->execute([$id,$me['id']]);$attempt=$q->fetch();
if(!$attempt){echo '<div class="card">Ujian tidak ditemukan.</div>';}elseif($attempt['status']!=='ongoing'){go('index.php?result='.$id);}else{if(time()>=(int)$attempt['deadline']){$_POST=['csrf'=>csrf(),'action'=>'submit_exam','attempt_id'=>$id];echo '<script>location.href="index.php?result='.$id.'"</script>'; $q=$db->prepare("UPDATE attempts SET status='submitted',submitted_at=CURRENT_TIMESTAMP WHERE id=?");$q->execute([$id]);} $packed=json_decode($attempt['answers'],true)?:[];$order=$packed['questions']??[];$optionOrder=$packed['options']??[];$answers=json_decode($attempt['answers'],true)?:[];$doubt=json_decode($attempt['doubtful'],true)?:[];$pos=max(0,(int)($_GET['q']??0));if(isset($_GET['qid'])){$pos=max(0,(int)array_search((int)$_GET['qid'],$order,true));} $pos=min($pos,max(0,count($order)-1));$questionId=(int)($order[$pos]??0);$q=$db->prepare('SELECT * FROM questions WHERE id=? AND exam_id=?');$q->execute([$questionId,$attempt['exam_id']]);$question=$q->fetch();$opts=$question?json_decode($question['options'],true):[];$ord=$optionOrder[$questionId]??array_keys($opts);$duration=max(0,(int)$attempt['deadline']-time()); ?>
<div class="row hero"><div><div class="eyebrow">Sedang mengerjakan · Kelas <?=h($attempt['grade'])?></div><h1><?=h($attempt['title'])?></h1><p><?=h($attempt['subject'])?> · <?=count($order)?> soal</p></div><div class="card" style="padding:12px 19px;text-align:center"><small class="muted">Sisa waktu</small><div class="timer" id="timer">--:--</div></div></div><div class="testlayout"><section class="card"><div class="row"><span class="badge">Soal <?=($pos+1)?> dari <?=count($order)?></span><span class="muted" style="font-size:13px">Jawaban tersimpan otomatis</span></div><?php if($question): ?><div class="question"><?=nl2br(h($question['prompt']))?></div><div id="choices"><?php foreach($ord as $display=>$oi): ?><label class="choice"><input type="radio" name="choice" value="<?=$oi?>" <?=isset($answers[(string)$questionId])&&(int)$answers[(string)$questionId]===(int)$oi?'checked':''?>><span><b><?=chr(65+$display)?>.</b> <?=h((string)$opts[$oi])?></span></label><?php endforeach ?></div><?php endif ?><div class="row" style="margin-top:22px"><button class="btn secondary" onclick="moveTo(<?=max(0,$pos-1)?>)" <?= $pos===0?'disabled':'' ?>>← Sebelumnya</button><button class="btn" onclick="moveTo(<?=min(count($order)-1,$pos+1)?>)">Berikutnya →</button></div></section><aside class="card"><div class="row"><h3>Navigasi soal</h3><span class="muted"><?=count($order)?> soal</span></div><div class="numbers"><?php foreach($order as $i=>$qid):$answered=isset($answers[(string)$qid]); ?><button class="num <?=$answered?'answered':''?> <?=in_array((int)$qid,$doubt,true)?'doubt':''?> <?=$i===$pos?'current':''?>" onclick="location.href='index.php?take=<?=$id?>&q=<?=$i?>'"><?=$i+1?></button><?php endforeach ?></div><div class="legend"><span><i class="dot"></i>Sudah dijawab</span><span><i class="dot gold"></i>Ragu-ragu</span><span>□ Belum dijawab</span></div><form method="post" style="margin:15px 0"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><input type="hidden" name="action" value="toggle_doubt"><input type="hidden" name="attempt_id" value="<?=$id?>"><input type="hidden" name="question_id" value="<?=$questionId?>"><button class="btn secondary" style="width:100%">☆ <?=in_array($questionId,$doubt,true)?'Hapus tanda ragu':'Tandai ragu-ragu'?></button></form><form method="post" onsubmit="return confirm('Kirim jawaban dan akhiri ujian?')"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><input type="hidden" name="action" value="submit_exam"><input type="hidden" name="attempt_id" value="<?=$id?>"><button class="btn danger" style="width:100%">Selesaikan ujian</button></form></aside></div><script>
const csrfToken=<?=json_encode(csrf())?>, attemptId=<?=$id?>, currentQuestion=<?=$questionId?>, deadline=<?=(int)$attempt['deadline']?>;
async function saveChoice(){const selected=document.querySelector('input[name="choice"]:checked');const data=new URLSearchParams({csrf:csrfToken,action:'save_answer',attempt_id:attemptId,question_id:currentQuestion,choice:selected?selected.value:'-1',ajax:'1'});try{await fetch('index.php',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:data})}catch(e){}}
document.querySelectorAll('input[name="choice"]').forEach(el=>el.addEventListener('change',saveChoice));function moveTo(n){saveChoice().finally(()=>location.href='index.php?take='+attemptId+'&q='+n)}
let remaining=deadline-Math.floor(Date.now()/1000);function tick(){remaining=deadline-Math.floor(Date.now()/1000);if(remaining<=0){document.getElementById('timer').textContent='00:00';fetch('index.php',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:new URLSearchParams({csrf:csrfToken,action:'submit_exam',attempt_id:attemptId})}).finally(()=>location.href='index.php?result='+attemptId);return}document.getElementById('timer').textContent=String(Math.floor(remaining/60)).padStart(2,'0')+':'+String(remaining%60).padStart(2,'0')}tick();setInterval(tick,1000);
</script><?php } ?>
<?php elseif(isset($_GET['result']) && $me['role']==='student'):$id=(int)$_GET['result'];$q=$db->prepare('SELECT a.*,e.title,e.subject FROM attempts a JOIN exams e ON e.id=a.exam_id WHERE a.id=? AND a.user_id=?');$q->execute([$id,$me['id']]);$r=$q->fetch();?><div class="hero"><div class="eyebrow">Hasil ujian</div><h1><?=h($r['title']??'Hasil tidak ditemukan')?></h1><p><?=h($r['subject']??'')?></p></div><?php if($r): ?><div class="card" style="max-width:600px"><div class="eyebrow">Nilai Anda</div><div style="font-size:50px;font-weight:900;color:var(--green);letter-spacing:-.06em"><?=$r['total']?round(100*$r['score']/$r['total']):0?><span style="font-size:20px">/100</span></div><p><?= (int)$r['score']?> jawaban benar dari <?= (int)$r['total']?> soal · Status: <?=h($r['status']==='submitted'?'Selesai':'Berlangsung')?></p><a class="btn" href="index.php" style="display:inline-block;text-decoration:none">Kembali ke beranda</a></div><?php endif ?>
