ng:15px 0"><div class="row"><div><strong><?=h($exam['title'])?></strong><div class="muted" style="font-size:13px"><?=h($exam['subject'])?> · Kelas <?=h($exam['grade'])?> · <?=$exam['duration']?> menit · <?=$exam['questions']?> soal</div></div><span class="badge">Aktif</span></div><details style="margin-top:10px"><summary style="cursor:pointer;color:var(--green);font-weight:700">+ Tambah soal pilihan ganda</summary><form method="post" style="padding:12px 0"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><input type="hidden" name="action" value="add_question"><input type="hidden" name="exam_id" value="<?=$exam['id']?>"><div class="field"><label>Pertanyaan</label><textarea name="prompt" required placeholder="Tulis pertanyaan di sini"></textarea></div><?php foreach(['A','B','C','D'] as $i=>$letter):?><div class="field"><label>Pilihan <?=$letter?></label><input name="options[]" required></div><?php endforeach ?><div class="field"><label>Jawaban benar</label><select name="correct"><?php foreach(['A','B','C','D'] as $i=>$letter):?><option value="<?=$i?>"><?=$letter?></option><?php endforeach ?></select></div><button class="btn small">Simpan soal</button></form></details></div><?php endforeach ?></section></div><section class="card" style="margin-top:18px"><div class="row"><div><h2>Rekap nilai siswa</h2><div class="muted">Hasil ujian yang sudah dikumpulkan</div></div><span class="badge"><?=count($results)?> hasil terbaru</span></div><?php if($results):?><div class="tablewrap"><table><thead><tr><th>Siswa</th><th>NISN / Username</th><th>Kelas</th><th>Ujian</th><th>Nilai</th><th>Status</th></tr></thead><tbody><?php foreach($results as $r):?><tr><td><?=h($r['name'])?></td><td><?=h($r['username'])?></td><td><?=h($r['grade'])?></td><td><?=h($r['title'])?> <span class="muted">(<?=h($r['subject'])?>)</span></td><td><strong><?=$r['total']?round(100*$r['score']/$r['total']):0?></strong> <span class="muted">/100</span></td><td><?=h($r['status']==='submitted'?'Selesai':'Berlangsung')?></td></tr><?php endforeach ?></tbody></table></div><?php else:?><p class="muted">Belum ada nilai yang masuk.</p><?php endif ?></section>
<?php else:$q=$db->prepare('SELECT e.*,COUNT(q.id) questions FROM exams e LEFT JOIN questions q ON q.exam_id=e.id WHERE e.active=1 AND e.grade=? GROUP BY e.id ORDER BY e.id DESC');$q->execute([$me['grade']]);$exams=$q->fetchAll();$q=$db->prepare("SELECT a.id,a.exam_id,a.score,a.total,a.status,e.title,e.subject FROM attempts a JOIN exams e ON e.id=a.exam_id WHERE a.user_id=? ORDER BY a.id DESC");$q->execute([$me['id']]);$attempts=$q->fetchAll();?><div class="hero"><div class="eyebrow">Beranda siswa · Kelas <?=h($me['grade'])?></div><h1>Assalamu'alaikum, <?=h($me['name'])?> 👋</h1><p>Siap belajar dan menunjukkan kemampuan terbaikmu hari ini?</p></div><div class="stats"><div class="stat"><strong><?=count($exams)?></strong><span class="muted">Ujian tersedia</span></div><div class="stat"><strong><?=count(array_filter($attempts,fn($a)=>$a['status']==='submitted'))?></strong><span class="muted">Ujian selesai</span></div></div><div class="row" style="margin:24px 0 13px"><h2>Ujian untukmu</h2><span class="muted">Kelas <?=h($me['grade'])?></span></div><?php if($exams):?><div class="grid"><?php foreach($exams as $exam):?><article class="card"><span class="badge"><?=h($exam['subject'])?></span><h2 style="margin-top:14px"><?=h($exam['title'])?></h2><div class="meta"><span class="muted">Kelas <?=h($exam['grade'])?></span><span class="muted">·</span><span class="muted"><?=$exam['questions']?> soal</span><span class="muted">·</span><span class="muted"><?=$exam['duration']?> menit</span></div><?php if(!$exam['questions']):?><button class="btn secondary" disabled>Soal belum tersedia</button><?php else:?><form method="post" onsubmit="return confirm('Mulai ujian? Waktu akan langsung berjalan.')"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><input type="hidden" name="action" value="start"><input type="hidden" name="exam_id" value="<?=$exam['id']?>"><button class="btn">Mulai ujian →</button></form><?php endif ?></article><?php endforeach ?></div><?php else:?><div class="card"><h3>Belum ada ujian</h3><p class="muted">Ujian baru akan muncul di sini setelah guru menyiapkannya.</p></div><?php endif ?><h2 style="margin:30px 0 13px">Riwayat ujian</h2><section class="card"><?php if($attempts):?><div class="tablewrap"><table><thead><tr><th>Ujian</th><th>Mata pelajaran</th><th>Status</th><th>Nilai</th><th></th></tr></thead><tbody><?php foreach($attempts as $a):?><tr><td><?=h($a['title'])?></td><td><?=h($a['subject'])?></td><td><?=h($a['status']==='submitted'?'Selesai':'Berlangsung')?></td><td><?=$a['status']==='submitted'?round(100*$a['score']/max(1,$a['total'])).'/100':'—'?></td><td><?php if($a['status']==='ongoing'):?><a href="index.php?take=<?=$a['id']?>">Lanjutkan</a><?php else:?><a href="index.php?result=<?=$a['id']?>">Lihat hasil</a><?php endif ?></td></tr><?php endforeach ?></tbody></table></div><?php else:?><p class="muted">Riwayat ujianmu akan tampil di sini.</p><?php endif ?></section><?php endif ?></main><footer class="footer">MTs Darul Muhsinin NW Surabaya Utara · CBT <?=date('Y')?></footer><?php endif ?></body></html>
